sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
try {
    var symphony_rec = current.response_to.agent_correlator.toString();
    var response = "";

    var xmlDoc = new XMLDocument2();
    xmlDoc.parseXML(current.payload.toString());
    response = xmlDoc.getNodeText("//result/output");
    var http_code_node = xmlDoc.getNode("//parameters/parameter");
    var http_code = http_code_node.getAttribute('value');
    var msg_code = xmlDoc.getNodeText("//output");
    var msg_code_obj = JSON.parse(msg_code);
    var message_response = msg_code_obj.message;

    var gr_sr = new GlideRecord("x_hsb11_mss_sw_hsbc_outbound_symphony_message_log");
    gr_sr.get(symphony_rec);
    gr_sr.response_date = new GlideDateTime();
    gr_sr.response_code = http_code;

    if (http_code == '200') {
        gr_sr.state = "Processed";
        gr_sr.response_body = response;
    } else {
        gr_sr.state = "Error";
        gr_sr.error_body = response;
        gr_sr.response_message = message_response;
        }
        gr_sr.update();
    } catch (e) {

    }
})(current, previous);
